package local.tvmorph.tv;
import java.net.*;import java.io.*;import javax.net.ssl.*;import java.security.cert.*;import android.content.Context;import java.util.*;
final class LanHttpClient {
 static final java.util.Map<Context,java.util.Set<HttpURLConnection>> active=java.util.Collections.synchronizedMap(new java.util.WeakHashMap<>());
 static void cancel(Context owner){synchronized(active){java.util.Set<HttpURLConnection> calls=active.remove(owner);if(calls!=null)for(HttpURLConnection c:calls)c.disconnect();}}
 static final int LIMIT=1024*1024;
 static class Reply{byte[] bytes;String type,host;Reply(byte[] b,String t,String h){bytes=b;type=t;host=h;}}
 static final class Target{final URI uri;final String ip;final HttpURLConnection connection;Target(URI u,String i,HttpURLConnection c){uri=u;ip=i;connection=c;}}
 static Target open(String address)throws Exception{
  URI u=LanPolicy.validate(address);InetAddress[] resolved=InetAddress.getAllByName(u.getHost());for(InetAddress a:resolved)if(!LanPolicy.local(a))throw new IOException("Device address changed outside local network.");InetAddress pinned=resolved[0];String host=u.getHost();String ip=pinned.getHostAddress();URI target=new URI(u.getScheme()+"://"+(ip.contains(":")?"["+ip+"]":ip)+(u.getPort()<0?"":":"+u.getPort())+(u.getRawPath()==null||u.getRawPath().isEmpty()?"/":u.getRawPath())+(u.getRawQuery()==null?"":"?"+u.getRawQuery()));HttpURLConnection c=(HttpURLConnection)target.toURL().openConnection();
  // Pin transport IP while validating TLS against the user's original hostname.
  if(c instanceof HttpsURLConnection){final SSLSocketFactory base=(SSLSocketFactory)SSLSocketFactory.getDefault();final String peer=host;final int port=u.getPort()<0?443:u.getPort();((HttpsURLConnection)c).setSSLSocketFactory(new SSLSocketFactory(){public String[] getDefaultCipherSuites(){return base.getDefaultCipherSuites();}public String[] getSupportedCipherSuites(){return base.getSupportedCipherSuites();}public java.net.Socket createSocket(java.net.Socket s,String h,int p,boolean close)throws IOException{return base.createSocket(s,peer,p,close);}public java.net.Socket createSocket(String h,int p)throws IOException{return base.createSocket(new java.net.Socket(pinned,p),peer,p,true);}public java.net.Socket createSocket(String h,int p,InetAddress l,int lp)throws IOException{java.net.Socket s=new java.net.Socket();s.bind(new InetSocketAddress(l,lp));s.connect(new InetSocketAddress(pinned,p),4000);return base.createSocket(s,peer,p,true);}public java.net.Socket createSocket(InetAddress h,int p)throws IOException{return createSocket(peer,p);}public java.net.Socket createSocket(InetAddress h,int p,InetAddress l,int lp)throws IOException{return createSocket(peer,p,l,lp);}});final HostnameVerifier verifier=HttpsURLConnection.getDefaultHostnameVerifier();((HttpsURLConnection)c).setHostnameVerifier((ignored,session)->verifier.verify(peer,session));}
  return new Target(u,ip,c);
 }
 static Reply request(Context context,String address,String method,String body,String soap,boolean probe)throws Exception{
  Target target=open(address);URI u=target.uri;String ip=target.ip;HttpURLConnection c=target.connection;
  synchronized(active){active.computeIfAbsent(context,k->new java.util.HashSet<>()).add(c);}long deadline=System.nanoTime()+10000000000L;
  try{c.setConnectTimeout(4000);c.setReadTimeout(6000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Host",u.getRawAuthority());c.setRequestProperty("User-Agent","MorphTV LocalNetwork/1");String auth=LanVault.auth(context,LanPolicy.origin(u));if(!auth.isEmpty())c.setRequestProperty("Authorization",auth);if(probe)c.setRequestProperty("Range","bytes=0-1023");c.setRequestMethod(method);if(method.equals("POST")){c.setDoOutput(true);c.setRequestProperty("Content-Type","text/xml; charset=utf-8");c.setRequestProperty("SOAPAction",soap);byte[] bytes=body.getBytes("UTF-8");if(bytes.length>65536)throw new IOException("Request too large.");c.getOutputStream().write(bytes);}int status=c.getResponseCode();if(status<200||status>299)throw new IOException(status==401||status==403?"Receiver authentication/access denied (HTTP "+status+").":"Local device HTTP "+status+". Redirects are not followed.");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){if(System.nanoTime()>deadline)throw new SocketTimeoutException();if(probe){out.write(bytes,0,Math.min(n,1024-out.size()));if(out.size()>=1024)break;}else{if(out.size()+n>LIMIT)throw new IOException("Device response exceeds 1 MiB.");out.write(bytes,0,n);}if(Thread.currentThread().isInterrupted())throw new IOException("Cancelled.");}}return new Reply(out.toByteArray(),c.getContentType()==null?"":c.getContentType(),ip);}catch(SocketTimeoutException e){throw new IOException("Local device timed out. Check power, network and streaming limits.");}finally{synchronized(active){java.util.Set<HttpURLConnection> calls=active.get(context);if(calls!=null){calls.remove(c);if(calls.isEmpty())active.remove(context);}}c.disconnect();}
 }
}
